#!/usr/bin/env bash
# Patches the Xcode project generated by `npx cap add ios` (CI, macOS). Run from ios-poc/.
# Env: REVERSED_CLIENT_ID (optional) — the Google iOS client's URL scheme.
set -euo pipefail
APP=ios/App/App
PL="$APP/Info.plist"
AD="$APP/AppDelegate.swift"
pb() { /usr/libexec/PlistBuddy -c "$1" "$PL"; }
pbtry() { /usr/libexec/PlistBuddy -c "$1" "$PL" >/dev/null 2>&1 || true; }

pbtry "Delete :CFBundleDisplayName"; pb "Add :CFBundleDisplayName string \"Baseline POC\""

# Background refresh: Info.plist only (no entitlement needed).
pbtry "Delete :UIBackgroundModes"
pb "Add :UIBackgroundModes array"
pb "Add :UIBackgroundModes:0 string fetch"
pb "Add :UIBackgroundModes:1 string processing"
pbtry "Delete :BGTaskSchedulerPermittedIdentifiers"
pb "Add :BGTaskSchedulerPermittedIdentifiers array"
pb "Add :BGTaskSchedulerPermittedIdentifiers:0 string app.baseline.poc.refresh"

# HealthKit probe (only active in the HealthKit variant, which flips this flag after the build).
pbtry "Delete :NSHealthShareUsageDescription"
pb "Add :NSHealthShareUsageDescription string \"Feasibility test: can Baseline read Apple Health when signed with a free Apple ID?\""
pbtry "Delete :BaselineHealthKitTest"
pb "Add :BaselineHealthKitTest bool false"

# Google OAuth redirect (reversed client ID scheme).
if [ -n "${REVERSED_CLIENT_ID:-}" ]; then
  pbtry "Delete :CFBundleURLTypes"
  pb "Add :CFBundleURLTypes array"
  pb "Add :CFBundleURLTypes:0 dict"
  pb "Add :CFBundleURLTypes:0:CFBundleURLName string google-oauth"
  pb "Add :CFBundleURLTypes:0:CFBundleURLSchemes array"
  pb "Add :CFBundleURLTypes:0:CFBundleURLSchemes:0 string $REVERSED_CLIENT_ID"
fi

# Native probes: append to AppDelegate.swift (no new file to add to the Xcode target) and call register() at launch.
cat native/BackgroundAndHealthKit.swift >> "$AD"
perl -0pi -e 's/^import UIKit\n/import UIKit\nimport BackgroundTasks\nimport HealthKit\n/m' "$AD"
perl -0pi -e 's/(didFinishLaunchingWithOptions[^{]*\{)/$1\n        BaselinePOCNative.register()/' "$AD"
grep -q "import BackgroundTasks" "$AD" || { echo "::error::AppDelegate import patch failed"; exit 1; }
grep -q "BaselinePOCNative.register()" "$AD" || { echo "::error::AppDelegate launch patch failed"; exit 1; }
echo "Patched Info.plist and AppDelegate.swift"
